const hubshellHome: Record<string, Record<string, string>> = Object.fromEntries(L.map((l) => [l, {}]));
ROWS.forEach((row) => {
  const [key, ...vals] = row;
  if (vals.length !== L.length) throw new Error(`hubshell-parts/home: "${key}" has ${vals.length} values, expected ${L.length}`);
  L.forEach((l, i) => { hubshellHome[l][key] = vals[i]; });
});
export default hubshellHome;
